#include <string>
#include <vector>

class Solution {
public:
    std::string mergeCloseCharacters(std::string s, int k) {
        std::vector<std::pair<char, int>> st;
        for (char ch : s) {
            if (!st.empty() && st.back().first == ch) {
                st.back().second++;
                if (st.back().second == k) st.pop_back();
            } else {
                st.push_back({ch, 1});
            }
        }
        std::string res = "";
        for (auto& p : st) {
            res.append(p.second, p.first);
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public String mergeCloseCharacters(String s, int k) {
        Deque<int[]> st = new ArrayDeque<>();
        for (char ch : s.toCharArray()) {
            if (!st.isEmpty() && st.peek()[0] == ch) {
                st.peek()[1]++;
                if (st.peek()[1] == k) st.pop();
            } else {
                st.push(new int[]{ch, 1});
            }
        }
        StringBuilder sb = new StringBuilder();
        while (!st.isEmpty()) {
            int[] top = st.removeLast();
            for (int i = 0; i < top[1]; i++) sb.append((char)top[0]);
        }
        return sb.toString();
    }
}

function mergeCloseCharacters(s, k) {
    const stack = [];
    for (const ch of s) {
        if (stack.length > 0 && stack[stack.length - 1][0] === ch) {
            stack[stack.length - 1][1]++;
            if (stack[stack.length - 1][1] === k) {
                stack.pop();
            }
        } else {
            stack.push([ch, 1]);
        }
    }
    return stack.map(([ch, cnt]) => ch.repeat(cnt)).join('');
}
